# -*- coding: utf-8 -*-
import base64, json
d = json.loads(base64.b64decode('').decode('utf-8'))
V = env['ir.ui.view'].sudo()
v = V.search([('key', '=', 'website.contactus'), ('website_id', '=', 1)], limit=1)
if not v:
    v = V.search([('key', '=', 'website.contactus')], limit=1)
for lang, val in d.items():
    if val:
        v.with_context(lang=lang).arch_db = val
env.cr.commit()
print('CU_APPLIED', [(l, len(x)) for l, x in d.items()])
